CREATE TABLE win14_scores (player_id INTEGER PRIMARY KEY, player_name TEXT NOT NULL, score INTEGER NOT NULL);
INSERT INTO win14_scores VALUES (1, 'Asha', 100), (2, 'Bilal', 90), (3, 'Chitra', 90), (4, 'Dinesh', 80);
SELECT player_name, score, RANK() OVER (ORDER BY score DESC) AS score_rank FROM win14_scores ORDER BY score DESC, player_name;

